var gen = UnityEngine.Object.FindObjectOfType<GraphLevelGenerator>();
if (gen != null) {
    var report = new System.Text.StringBuilder();
    report.AppendLine("Normal: " + gen.normalRoomPrefabs.Length);
    foreach(var p in gen.normalRoomPrefabs) report.AppendLine(p.name);
    report.AppendLine("Reward: " + gen.rewardRoomPrefabs.Length);
    foreach(var p in gen.rewardRoomPrefabs) report.AppendLine(p.name);
    report.AppendLine("DeadEnd: " + gen.deadEndRoomPrefabs.Length);
    foreach(var p in gen.deadEndRoomPrefabs) report.AppendLine(p.name);
    System.IO.File.WriteAllText("GeneratorPools.txt", report.ToString());
}
